use lg_core::{AccountId, Date};
use lg_parse::{parse_statement, StatementOptions};

#[test]
fn disc_l06() {
    let text = "data;descricao;valor\n29/02/2000;SALDO ANTERIOR;10,00\n2400-02-29;FUTURO;1,00\n";
    let opts = StatementOptions::new(AccountId::parse("ativo:banco").unwrap());
    let txns = parse_statement(text, &opts).unwrap();
    assert_eq!(txns[0].date.to_string(), "2000-02-29");
    assert_eq!(txns.len(), 2);
    assert!(Date::parse_any("1900-02-29").is_err());
}
